CREATE OR REPLACE PROCEDURE sp(
    arg1 VARCHAR2,
    arg2 NUMBER,
    arg3 VARCHAR2,
    arg4 VARCHAR2
)
AS
    v_mascot_match_count NUMBER;
    v_budgeted_avg       NUMBER;
    v_enrollment_avg     NUMBER;
    v_updated_count      NUMBER := 0;
    e_no_school_match    EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_no_school_match, -20002);
    e_no_update          EXCEPTION;
    PRAGMA EXCEPTION_INIT(e_no_update, -20001);
BEGIN
    SAVEPOINT acorn_peg;

    -- Step 2: Determine Mascot match count
    SELECT COUNT(*)
      INTO v_mascot_match_count
      FROM "School"
     WHERE "Mascot" = arg3;

    IF v_mascot_match_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20002, 'No School record matches the mascot; budget updates skipped');
    END IF;

    -- Step 3: Compute Budgeted average and Enrollment average (fall-line constant)
    SELECT AVG("Budgeted")
      INTO v_budgeted_avg
      FROM "budget";

    SELECT AVG("Enrollment")
      INTO v_enrollment_avg
      FROM "School";

    -- Step 4: Budget pass
    FOR rec IN (SELECT "School_id", "Year", "Budget_invested_percent",
                       "total_budget_percent_budgeted", "Budgeted"
                  FROM "budget")
    LOOP
        IF rec."Budget_invested_percent" = arg1
           AND rec."total_budget_percent_budgeted" <= arg2
           AND rec."Budgeted" <= v_budgeted_avg
        THEN
            UPDATE "budget"
               SET "total_budget_percent_budgeted" = arg2
             WHERE "School_id" = rec."School_id"
               AND "Year" = rec."Year";
            v_updated_count := v_updated_count + 1;
        END IF;
    END LOOP;

    -- Step 5: School pass
    FOR rec IN (SELECT "School_id", "Mascot", "Enrollment"
                  FROM "School")
    LOOP
        IF rec."Mascot" = arg3
           AND rec."Enrollment" > v_enrollment_avg
        THEN
            UPDATE "School"
               SET "Location" = arg4
             WHERE "School_id" = rec."School_id";
            v_updated_count := v_updated_count + 1;
        END IF;
    END LOOP;

    -- Step 6: Check updated-row count
    IF v_updated_count = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'No matching records were updated');
    END IF;

EXCEPTION
    WHEN OTHERS THEN
        ROLLBACK TO acorn_peg;
        RAISE;
END sp;

